                                                                                                                                                                                                       
  CREATE TABLE "CHECK_OBJECT"                                                                                                                                                               
   (	"OBJECT_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                 
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"UPDATED_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                  
	"REMARK" NVARCHAR2(512),                                                                                                                                                                              
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                   
	"EXT_ORG_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                            
	"CATEGORY_FIRST_CODE" NVARCHAR2(64) NOT NULL ENABLE,                                                                                                                                                  
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                     
	"APPLY_ALL" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                    
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                         
	"DEPT_ID" NUMBER,                                                                                                                                                                                     
	"FIRST_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                        
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                    
	"OBJECT_SERIAL_NO" NVARCHAR2(200),                                                                                                                                                                    
	"IS_REVIEW" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                         
	"REVIEW_USERS" NVARCHAR2(1000),                                                                                                                                                                       
	 PRIMARY KEY ("OBJECT_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                  
   ) ;                                                                                                                                                                                                 

